<?php require_once __DIR__.'/include/config.php';require_once __DIR__.'/../include/billing.php';hms_start_session();hms_require_role('admin');$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT)?:0;if(!hms_billing_ready($con))exit(hms_billing_notice());$invoice=hms_db_query($con,'SELECT i.*,u.fullName patient,u.email FROM billing_invoices i JOIN users u ON u.id=i.patient_user_id WHERE i.id=?',[$id])->fetch_assoc();if(!$invoice){http_response_code(404);exit('Invoice not found.');}$items=hms_db_query($con,'SELECT * FROM billing_invoice_items WHERE invoice_id=?',[$id]);$payments=hms_db_query($con,'SELECT * FROM billing_payments WHERE invoice_id=? ORDER BY received_at DESC',[$id]);?>
<!doctype html><html><head><meta charset="utf-8"><title><?=hms_h($invoice['invoice_number'])?></title><link rel="stylesheet" href="vendor/bootstrap/css/bootstrap.min.css"><style>body{background:#f4f8fc;color:#172b4d;font:14px/1.55 Inter,Segoe UI,Arial,sans-serif}.invoice{max-width:920px;margin:32px auto;padding:36px;background:#fff;border:1px solid #e2eaf0;border-radius:14px;box-shadow:0 10px 30px rgba(18,48,74,.08)}.invoice>a{color:#1769aa;font-weight:700}.invoice>h1{margin:25px 0 4px;color:#12304a;font-size:27px}.invoice>h2{margin:0 0 20px;color:#1769aa;font-size:18px}.invoice>p{padding:15px 17px;background:#f7fafc;border:1px solid #e2eaf0;border-radius:10px;color:#40566b}.invoice .table{margin:16px 0;border:1px solid #e2eaf0;border-radius:10px;overflow:hidden}.invoice .table>thead>tr>th,.invoice .table>tr>th{padding:12px;background:#f3f8fc;color:#60748a;font-size:11px;text-transform:uppercase;letter-spacing:.04em}.invoice .table>tbody>tr>td,.invoice .table>tr>td{padding:12px;vertical-align:middle}.invoice h3{margin:26px 0 10px;font-size:16px}.invoice form{display:flex;align-items:center;gap:9px;flex-wrap:wrap;padding:16px;background:#f7fafc;border:1px solid #e2eaf0;border-radius:10px}.invoice form input,.invoice form select{min-height:40px;padding:8px 10px;border:1px solid #cad8e5;border-radius:8px}.invoice .btn{min-height:40px;border-radius:8px;font-weight:700}@media(max-width:640px){body{background:#fff}.invoice{margin:0;padding:20px;border:0;border-radius:0;box-shadow:none}.invoice .table{min-width:620px}.invoice form{align-items:stretch;flex-direction:column}.invoice form input,.invoice form select,.invoice form button{width:100%}}@media print{body{background:#fff}.invoice{max-width:none;margin:0;padding:0;border:0;box-shadow:none}.invoice button,.invoice>a,.invoice form{display:none}.invoice .table{border:1px solid #ccd6df}}</style></head><body><main class="invoice"><a href="billing.php">Back</a><button onclick="print()" class="btn btn-primary pull-right">Print invoice</button><h1>MedTech Hospital</h1><h2>Invoice <?=hms_h($invoice['invoice_number'])?></h2><p><b>Patient:</b> <?=hms_h($invoice['patient'])?> · <?=hms_h($invoice['email'])?><br><b>Issued:</b> <?=hms_h($invoice['issue_date'])?> · <b>Status:</b> <?=hms_h($invoice['status'])?></p><table class="table table-bordered"><tr><th>Description</th><th>Qty</th><th>Unit price</th><th>Total</th></tr><?php while($item=$items->fetch_assoc()):?><tr><td><?=hms_h($item['description'])?></td><td><?=hms_h($item['quantity'])?></td><td>₹<?=number_format((float)$item['unit_price'],2)?></td><td>₹<?=number_format((float)$item['line_total'],2)?></td></tr><?php endwhile;?></table><p>Subtotal ₹<?=number_format((float)$invoice['subtotal'],2)?> · Discount ₹<?=number_format((float)$invoice['discount_amount'],2)?> · Tax ₹<?=number_format((float)$invoice['tax_amount'],2)?><br><b>Total ₹<?=number_format((float)$invoice['total_amount'],2)?> · Paid ₹<?=number_format((float)$invoice['amount_paid'],2)?> · Balance ₹<?=number_format((float)$invoice['balance_amount'],2)?></b></p><h3>Payments</h3><table class="table"><tr><th>Receipt</th><th>Date</th><th>Amount</th><th>Method</th><th>Reference</th></tr><?php while($payment=$payments->fetch_assoc()):?><tr><td><a href="receipt.php?id=<?=hms_h($payment['id'])?>"><?=hms_h($payment['receipt_number'])?></a></td><td><?=hms_h($payment['received_at'])?></td><td>₹<?=number_format((float)$payment['amount'],2)?></td><td><?=hms_h($payment['payment_method'])?></td><td><?=hms_h($payment['transaction_reference'])?></td></tr><?php endwhile;?></table><?php if($invoice['balance_amount']>0):?><form method="post" action="billing.php"><?=hms_csrf_field()?><input type="hidden" name="action" value="payment"><input type="hidden" name="invoice_id" value="<?=hms_h($id)?>"><input type="number" name="amount" min=".01" max="<?=hms_h($invoice['balance_amount'])?>" step=".01" required><select name="payment_method"><option value="cash">Cash</option><option value="card">Card</option><option value="upi">UPI</option><option value="bank_transfer">Bank transfer</option><option value="insurance">Insurance</option></select><input name="reference" maxlength="120" placeholder="Reference"><button class="btn btn-success">Record payment</button></form><?php endif;?></main></body></html>
